CREATE TABLE el_employee_loans(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,employee_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('advance','loan')),principal INTEGER NOT NULL CHECK(typeof(principal)='integer' AND principal BETWEEN 1 AND 1000000000),receivable_account_id TEXT NOT NULL,requested_on TEXT NOT NULL,due_on TEXT NOT NULL CHECK(due_on>=requested_on),reason TEXT NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','rejected','cancelled','disbursed')),created_by TEXT NOT NULL,approved_by TEXT,decision_note TEXT NOT NULL DEFAULT '',decided_at INTEGER,disbursed_by TEXT,disbursed_on TEXT,disbursed_method TEXT CHECK(disbursed_method IN ('cash','bank')),journal_id TEXT,created_at INTEGER NOT NULL,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id),FOREIGN KEY(org_id,receivable_account_id) REFERENCES el_accounts(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,approved_by) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,disbursed_by) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,journal_id) REFERENCES el_journals(org_id,id));
CREATE INDEX el_employee_loan_branch ON el_employee_loans(org_id,branch_id,created_at,id);
CREATE TABLE el_employee_loan_recoveries(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,loan_id TEXT NOT NULL,date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount BETWEEN 1 AND 1000000000),method TEXT NOT NULL CHECK(method IN ('cash','bank')),reference TEXT NOT NULL,request_key TEXT NOT NULL,journal_id TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(org_id,id),UNIQUE(org_id,request_key),FOREIGN KEY(org_id,loan_id) REFERENCES el_employee_loans(org_id,id),FOREIGN KEY(org_id,journal_id) REFERENCES el_journals(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE INDEX el_employee_loan_recovery ON el_employee_loan_recoveries(org_id,loan_id,date,id);
CREATE TRIGGER el_employee_loan_insert BEFORE INSERT ON el_employee_loans BEGIN
 SELECT CASE WHEN NEW.status<>'draft' OR NEW.decided_at IS NOT NULL OR NEW.approved_by IS NOT NULL OR NEW.disbursed_by IS NOT NULL OR NEW.journal_id IS NOT NULL OR NEW.disbursed_on IS NOT NULL OR NEW.disbursed_method IS NOT NULL THEN RAISE(ABORT,'Employee loan must begin as a draft') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_employees e JOIN el_organizations o ON o.id=e.org_id JOIN el_accounts a ON a.id=NEW.receivable_account_id AND a.org_id=e.org_id WHERE e.id=NEW.employee_id AND e.org_id=NEW.org_id AND e.branch_id=NEW.branch_id AND e.status IN ('active','onboarding','on_leave') AND e.is_demo=0 AND o.currency=NEW.currency AND a.kind='asset' AND a.active=1 AND a.system_key IS NULL) THEN RAISE(ABORT,'Employee loan employee currency or receivable account changed') END;
END;
CREATE TRIGGER el_employee_loan_update BEFORE UPDATE ON el_employee_loans BEGIN
 SELECT CASE WHEN NEW.id IS NOT OLD.id OR NEW.org_id IS NOT OLD.org_id OR NEW.branch_id IS NOT OLD.branch_id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.kind IS NOT OLD.kind OR NEW.principal IS NOT OLD.principal OR NEW.receivable_account_id IS NOT OLD.receivable_account_id OR NEW.requested_on IS NOT OLD.requested_on OR NEW.due_on IS NOT OLD.due_on OR NEW.reason IS NOT OLD.reason OR NEW.currency IS NOT OLD.currency OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at THEN RAISE(ABORT,'Employee loan terms are immutable') END;
 SELECT CASE WHEN NOT((OLD.status='draft' AND NEW.status IN ('approved','rejected') AND NEW.decided_at IS NOT NULL AND NEW.approved_by IS NOT NULL AND NEW.approved_by<>OLD.created_by AND NEW.disbursed_by IS NULL AND NEW.journal_id IS NULL AND NEW.disbursed_on IS NULL AND NEW.disbursed_method IS NULL) OR (OLD.status='approved' AND NEW.status='cancelled' AND NEW.decided_at IS NOT NULL AND NEW.approved_by IS OLD.approved_by AND NEW.disbursed_by IS NULL AND NEW.journal_id IS NULL AND NEW.disbursed_on IS NULL AND NEW.disbursed_method IS NULL) OR (OLD.status='approved' AND NEW.status='disbursed' AND NEW.decided_at IS OLD.decided_at AND NEW.approved_by IS OLD.approved_by AND NEW.decision_note IS OLD.decision_note AND NEW.disbursed_by IS NOT NULL AND NEW.disbursed_by<>OLD.created_by AND NEW.disbursed_by<>OLD.approved_by AND NEW.disbursed_on>=OLD.requested_on)) THEN RAISE(ABORT,'Employee loan requires an independent valid transition') END;
 SELECT CASE WHEN NEW.status='disbursed' AND NOT EXISTS(SELECT 1 FROM el_employees e JOIN el_organizations o ON o.id=e.org_id WHERE e.id=NEW.employee_id AND e.org_id=NEW.org_id AND e.branch_id=NEW.branch_id AND e.is_demo=0 AND e.status IN ('active','onboarding','on_leave') AND o.currency=NEW.currency) THEN RAISE(ABORT,'Employee loan employee branch status or currency changed') END;
 SELECT CASE WHEN NEW.status='disbursed' AND NOT EXISTS(SELECT 1 FROM el_journals j WHERE j.id=NEW.journal_id AND j.org_id=NEW.org_id AND j.branch_id=NEW.branch_id AND j.status='posted' AND j.date=NEW.disbursed_on AND j.source_type='employee_loan' AND j.source_id=NEW.id AND (SELECT count(*) FROM el_journal_lines WHERE journal_id=j.id)=2 AND EXISTS(SELECT 1 FROM el_journal_lines l WHERE l.journal_id=j.id AND l.account_id=NEW.receivable_account_id AND l.debit=NEW.principal AND l.credit=0) AND EXISTS(SELECT 1 FROM el_journal_lines l JOIN el_accounts a ON a.id=l.account_id WHERE l.journal_id=j.id AND a.org_id=NEW.org_id AND a.system_key=NEW.disbursed_method AND l.debit=0 AND l.credit=NEW.principal)) THEN RAISE(ABORT,'Employee loan disbursement needs matching posted journal') END;
END;
CREATE TRIGGER el_employee_loan_no_delete BEFORE DELETE ON el_employee_loans BEGIN SELECT RAISE(ABORT,'Employee loans cannot be deleted');END;
CREATE TRIGGER el_employee_loan_recovery_guard BEFORE INSERT ON el_employee_loan_recoveries BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_employee_loans p WHERE p.id=NEW.loan_id AND p.org_id=NEW.org_id AND p.status='disbursed' AND p.currency=(SELECT currency FROM el_organizations WHERE id=p.org_id) AND NEW.date>=p.disbursed_on AND NEW.amount<=p.principal-COALESCE((SELECT sum(amount) FROM el_employee_loan_recoveries WHERE loan_id=p.id),0) AND EXISTS(SELECT 1 FROM el_journals j WHERE j.id=NEW.journal_id AND j.org_id=p.org_id AND j.branch_id=p.branch_id AND j.status='posted' AND j.date=NEW.date AND j.source_type='employee_loan_recovery' AND j.source_id=NEW.id AND (SELECT count(*) FROM el_journal_lines WHERE journal_id=j.id)=2 AND EXISTS(SELECT 1 FROM el_journal_lines l WHERE l.journal_id=j.id AND l.account_id=p.receivable_account_id AND l.debit=0 AND l.credit=NEW.amount) AND EXISTS(SELECT 1 FROM el_journal_lines l JOIN el_accounts a ON a.id=l.account_id WHERE l.journal_id=j.id AND a.org_id=p.org_id AND a.system_key=NEW.method AND l.debit=NEW.amount AND l.credit=0))) THEN RAISE(ABORT,'Employee loan recovery exceeds balance or matching journal is unavailable') END;
END;
CREATE TRIGGER el_employee_loan_recovery_immutable BEFORE UPDATE ON el_employee_loan_recoveries BEGIN SELECT RAISE(ABORT,'Employee loan recoveries are immutable');END;
CREATE TRIGGER el_employee_loan_recovery_no_delete BEFORE DELETE ON el_employee_loan_recoveries BEGIN SELECT RAISE(ABORT,'Employee loan recoveries cannot be deleted');END;
